(function initOnline(){
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initOnline,{once:true});return}
if(window.MQOnline)return;
const API='https://tablegame.jujuli.com.cn/api',KEY='mq-online-room-v3';
let user=null,room=null,timer=0,sending=false,fetching=false,connected=false,active=false,dialog=null,generation=0,endedRevision=-1;
const style=document.createElement('style');style.textContent=`#onlineMode{opacity:1!important;cursor:pointer!important}.mq-auth{box-sizing:border-box;width:min(420px,calc(100vw - 32px));border:0;border-radius:24px;padding:26px;background:#fffaf0;color:#302f2a;box-shadow:0 24px 80px #0003;font:14px Microsoft YaHei,system-ui}.mq-auth::backdrop{background:#0006}.mq-auth h2{margin:0 0 10px}.mq-auth p{color:#756d61;line-height:1.7;overflow-wrap:anywhere}.mq-auth input{box-sizing:border-box;width:100%;padding:14px;margin:6px 0;border:1px solid #ddd3c3;border-radius:12px;font:inherit}.mq-auth button{width:100%;padding:13px;margin-top:9px;border:0;border-radius:12px;font:inherit;font-weight:700;cursor:pointer}.mq-auth button:disabled{opacity:.5;cursor:wait}.mq-auth .main{background:#302f2a;color:white}.mq-auth .sub{background:#f1eadf}.mq-auth .err{color:#a33;min-height:20px}.mq-user{border:0;background:transparent;font:inherit;padding:10px;cursor:pointer;max-width:180px;overflow:hidden;text-overflow:ellipsis}.mq-room-bar{display:flex;gap:8px;align-items:center;justify-content:space-between;font:13px Microsoft YaHei,system-ui;margin:0 0 16px}.mq-room-bar button{border:0;border-radius:10px;background:#eee8dd;padding:8px 12px;color:inherit}`;document.head.append(style);
async function api(path,data){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(API+path,{credentials:'include',signal:controller.signal,...(data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})});const result=await r.json();if(!r.ok){const e=Error(result.error||'网络请求失败');e.status=r.status;throw e}return result}finally{clearTimeout(timeout)}}
function modal(title,html){dialog?.close();dialog?.remove();const d=document.createElement('dialog');d.className='mq-auth';d.innerHTML='<h2></h2>'+html;d.querySelector('h2').textContent=title;document.body.append(d);dialog=d;d.addEventListener('close',()=>{if(dialog===d)dialog=null;d.remove()});d.showModal();return d}
function error(d,e){const el=d.querySelector('.err');if(el)el.textContent=e.name==='AbortError'?'连接超时，请重试':e.message}
function renderUser(){document.querySelector('.mq-user')?.remove();const b=document.createElement('button');b.className='mq-user';b.textContent=user?user.username:'登录';b.onclick=()=>user?account():login();document.querySelector('.header-right')?.prepend(b)}
function login(after){const d=modal('登录妙棋手','<p>与桌游大厅共用一个账号</p><form><input name="username" autocomplete="username" placeholder="用户名或邮箱" required><input name="password" autocomplete="current-password" type="password" placeholder="密码（至少10位）" minlength="10" required><div class="err" role="alert"></div><button class="main" type="submit">登录</button><button class="sub register" type="button">注册新账号</button><button class="sub cancel" type="button">取消</button></form>');let pending=false;async function submit(kind){if(pending||!d.querySelector('form').reportValidity())return;pending=true;d.querySelectorAll('button').forEach(b=>b.disabled=true);try{user=(await api('/'+kind,{username:d.querySelector('[name=username]').value,password:d.querySelector('[name=password]').value})).user;d.close();renderUser();after?.()}catch(e){error(d,e)}finally{pending=false;d.querySelectorAll('button').forEach(b=>b.disabled=false)}}d.querySelector('form').onsubmit=e=>{e.preventDefault();submit('login')};d.querySelector('.register').onclick=()=>submit('register');d.querySelector('.cancel').onclick=()=>d.close()}
function account(){const d=modal('桌游账号','<p class="name"></p><p>在妙棋手和桌游大厅中通用。</p><div class="err"></div><button class="main">返回</button><button class="sub">退出登录</button>');d.querySelector('.name').textContent=user.username;d.querySelector('.main').onclick=()=>d.close();d.querySelector('.sub').onclick=async()=>{try{await api('/logout',{});suspend();room=null;user=null;localStorage.removeItem(KEY);if(mode==='online'){mode=draftMode='ai';reset();navigate('home')}d.close();renderUser()}catch(e){error(d,e)}}}
function remember(){try{localStorage.setItem(KEY,JSON.stringify({code:room.code,user:user.id}))}catch{}}
function open(){if(!user)return login(open);const d=modal('联机对战',`<p>创建棋局，或输入好友发来的 8 位房间码。</p><button class="main create">创建新房间</button><input class="code" maxlength="8" placeholder="输入房间码" aria-label="房间码"><button class="sub join">加入房间</button>${room?'<button class="sub resume">返回当前房间</button>':''}<div class="err" role="alert"></div><button class="sub cancel">取消</button>`);let pending=false;async function enter(path,data){if(pending)return;pending=true;d.querySelectorAll('button').forEach(b=>b.disabled=true);try{const next=await api(path,data);suspend();room=next;connected=true;active=true;remember();d.close();enterGame();schedule()}catch(e){error(d,e)}finally{pending=false;d.querySelectorAll('button').forEach(b=>b.disabled=false)}}d.querySelector('.create').onclick=()=>enter('/chess/rooms',{});d.querySelector('.join').onclick=()=>{const code=d.querySelector('.code').value.trim().toUpperCase();if(!/^[A-F0-9]{8}$/.test(code)){error(d,Error('请输入正确的 8 位房间码'));return}enter('/chess/rooms/'+code,{type:'join'})};d.querySelector('.resume')?.addEventListener('click',()=>{d.close();active=true;enterGame();schedule()});d.querySelector('.cancel').onclick=()=>d.close()}
function suspend(){document.getElementById('mqRoomBar')?.setAttribute('hidden','');const top=document.querySelector('.board-heading small'),bottom=document.querySelector('.board-footer small');if(top)top.textContent='山隐 · 棋友';if(bottom)bottom.textContent='你执红 · 先手';active=false;generation++;clearTimeout(timer);connected=false;selected=null}
function enterGame(){epoch++;cancelComputer();busy=false;mode=draftMode='online';flipped=room.side==='b';drawAgreed=room.winner==='draw';resignedSide=room.winner&&room.winner!=='draw'?(room.winner==='r'?'b':'r'):null;selected=null;ended=false;endedRevision=-1;applyRoom();navigate('game');render();toast('房间 '+room.code+' · 你执'+(room.side==='r'?'红':'黑'))}
function applyRoom(){if(!room||!active||mode!=='online')return;board=room.board.map(row=>row.slice());turn=room.turn;last=room.last;let replay=XQ.initial();history=(room.moves||[]).map((m,i)=>{const snapshot=replay;replay=XQ.play(replay,m);return {board:snapshot,turn:i%2?'b':'r',label:`${i%2?'墨':'朱'} · ${XQ.names[m.piece[0]][m.piece[1]]} ${m.x+1},${m.y+1} → ${m.X+1},${m.Y+1}${m.captured?' · 吃子':''}`}});legal=XQ.moves(board,turn);ended=room.status==='ended';drawAgreed=room.winner==='draw';resignedSide=ended&&!drawAgreed?(room.winner==='r'?'b':'r'):null;selected=null;draw();if(ended&&endedRevision!==room.revision){endedRevision=room.revision;dialog?.close();if(pageView==='game')showResult()}}
function render(){const barId='mqRoomBar';let bar=document.getElementById(barId);if(!bar){bar=document.createElement('div');bar.id=barId;bar.className='mq-room-bar';bar.innerHTML='<span></span><button type="button">复制房间码</button>';document.getElementById('gameStage')?.prepend(bar);bar.querySelector('button').onclick=async()=>{try{await navigator.clipboard.writeText(room.code);toast('房间码已复制')}catch{toast('房间码：'+room.code)}}}bar.hidden=mode!=='online';if(mode!=='online'||!room)return;bar.querySelector('span').textContent=`房间 ${room.code} · 你执${room.side==='r'?'红':'黑'}`;const opponent=room.players.find(p=>p.side!==room.side);$('opponent').textContent=opponent?opponent.username:'等待好友加入';$('undo').disabled=true;$('offerDraw').disabled=ended||sending||!connected||room.status!=='playing'||!!room.drawOffer;$('resign').disabled=ended||sending||!connected;$('status').textContent=ended?(room.winner==='draw'?'和棋 · 双方同意':room.winner===room.side?'你赢得了本局':'对手赢得了本局'):!connected?'连接中，正在恢复…':room.status==='waiting'?'等待好友加入':sending?'正在提交…':turn===room.side?'轮到你落子':'等待对手落子';$('hint').textContent=ended?'本局结束，可以创建新房间':!connected?'网络恢复后自动同步棋局':room.status==='waiting'?'将房间码发给好友，加入后自动开始':room.drawOffer?(room.drawOffer===room.side?'已向对手发出求和请求':'对手请求和棋，请确认'):XQ.check(board,turn)?'将军！请先解将':turn===room.side?'轻触棋子，查看可行之处':'对手正在思考';const top=document.querySelector('.board-heading small'),bottom=document.querySelector('.board-footer small');if(top)top.textContent=room.players.find(p=>p.side==='b')?.username||'等待加入';if(bottom)bottom.textContent=(room.players.find(p=>p.side==='r')?.username||'')+' · 红方先手';$('continueGame').hidden=false}
function checkDraw(){if(!active||pageView!=='game'||!room||ended)return;if(room.drawOffer&&room.drawOffer!==room.side){if(dialog?.dataset.drawRevision===String(room.revision))return;const d=modal('对手提议和棋','<p>同意后本局以和棋结束；拒绝则继续对弈。</p><button class="main">同意和棋</button><button class="sub">继续对弈</button>');d.dataset.drawRevision=room.revision;d.querySelector('.main').onclick=()=>{d.close();action('acceptDraw')};d.querySelector('.sub').onclick=()=>{d.close();action('declineDraw')};d.addEventListener('cancel',e=>{e.preventDefault();d.close();action('declineDraw')})}else if(dialog?.dataset.drawRevision)dialog.close()}
function schedule(delay=1600){clearTimeout(timer);if(active)timer=setTimeout(sync,delay)}
async function sync(){if(!active||!room)return;if(sending||fetching){schedule();return}const g=generation,code=room.code;fetching=true;try{const next=await api('/chess/rooms/'+code);if(g!==generation||!active||sending||next.revision<room.revision)return;const changed=next.revision!==room.revision;room=next;connected=true;if(changed)applyRoom();else render();checkDraw()}catch(e){if(g!==generation)return;connected=false;selected=null;render();if([401,404,410].includes(e.status)){suspend();toast(e.message);if(e.status===401){user=null;renderUser()}try{localStorage.removeItem(KEY)}catch{}}}finally{fetching=false;if(g===generation)schedule(connected?1600:5000)}}
async function action(type,extra={}){if(!active||!room||sending||!connected)return;const g=generation;clearTimeout(timer);sending=true;render();try{const next=await api('/chess/rooms/'+room.code,{type,revision:room.revision,...extra});if(g!==generation||next.revision<room.revision)return;room=next;applyRoom();checkDraw()}catch(e){toast(e.name==='AbortError'?'提交超时，正在核对棋局':e.message);connected=false;selected=null}finally{sending=false;render();schedule(10)}}
function confirmation(title,type){if(!active||ended)return;const d=modal(title,'<p>操作将同步给对手。</p><button class="main">确认</button><button class="sub">取消</button>');d.querySelector('.main').onclick=()=>{d.close();action(type)};d.querySelector('.sub').onclick=()=>d.close()}
window.MQOnline={open,suspend,render,canMove:()=>active&&connected&&!sending&&room?.status==='playing'&&room.side===room.turn,move:m=>action('move',m),offerDraw:()=>confirmation('向对手提议和棋？','offerDraw'),resign:()=>confirmation('确认认输？','resign')};
const button=$('onlineMode');if(button){button.disabled=false;button.removeAttribute('title');button.setAttribute('aria-label','联机对战');button.querySelector('small').textContent='好友对战';button.onclick=()=>{draftMode='online';draw();open()}}
window.addEventListener('online',()=>{if(active)sync()});window.addEventListener('hashchange',()=>{if(mode==='online'&&active){render();checkDraw()}});
(async()=>{try{user=(await api('/me')).user;renderUser();if(!user)return;let saved;try{saved=JSON.parse(localStorage.getItem(KEY))}catch{}if(saved?.user!==user.id||!saved?.code)return;room=await api('/chess/rooms/'+saved.code);active=true;connected=true;if(location.hash==='#game')enterGame();else{const b=$('continueGame');b.hidden=false;b.textContent='返回联机房间 →';b.onclick=()=>enterGame()}schedule()}catch{renderUser()}})();
})();
